Dataspatium.assets.register("presets/api/plandata-dk.api.json","text","{\n \"format\": \"dataspatium-api/1\",\n \"id\": \"plandata-dk\",\n \"name\": \"Plandata.dk (WFS)\",\n \"publisher\": \"Plan- og Landdistriktsstyrelsen\",\n \"description\": \"Danmarks digitala planer: lokalplaner med delområden och byggefelter, kommuneplanrammer, kommuneplantillæg och zonkartor som WFS-lager med GeoJSON. Hämta ett lager som karta, eller hämta en hel lokalplan som plan med dess plannummer eller planid.\",\n \"docs\": \"https://www.plandata.dk/teknisk-information/\",\n \"license\": {\n  \"name\": \"Offentliga data från Plandata.dk\",\n  \"url\": \"https://www.plandata.dk/\"\n },\n \"level\": 1,\n \"country\": \"DK\",\n \"baseUrl\": \"https://geoserver.plandata.dk/geoserver/wfs\",\n \"auth\": {\n  \"type\": \"none\"\n },\n \"family\": {\n  \"type\": \"geodata\",\n  \"kind\": \"wfs\",\n  \"plans\": \"plandata\"\n },\n \"endpoints\": [],\n \"notes\": \"Lagren läses från tjänsten när källan öppnas (GetCapabilities, cirka 400 lager). Kodlistor finns som egna lager (pdk:theme_pdk_codelist_*). Plannummer (t.ex. 2024-05) kräver att kommunen begränsas med filtret komnr.\",\n \"i18n\": {\n  \"en\": {\n   \"name\": \"Plandata.dk (WFS)\",\n   \"description\": \"Denmark's digital plans: local plans with sub-areas and building fields, municipal plan frames, supplements and zoning as WFS layers in GeoJSON. Fetch a layer as a map, or a whole local plan as a plan by its plan number or planid.\",\n   \"notes\": \"The layers are read from the service when the source is opened (about 400 layers). Code lists are layers of their own (pdk:theme_pdk_codelist_*).\"\n  },\n  \"da\": {\n   \"name\": \"Plandata.dk (WFS)\",\n   \"description\": \"Danmarks digitale planer: lokalplaner med delområder og byggefelter, kommuneplanrammer, kommuneplantillæg og zonekort som WFS-lag i GeoJSON. Hent et lag som kort, eller en hel lokalplan som plan med plannummer eller planid.\",\n   \"notes\": \"Lagene læses fra tjenesten, når kilden åbnes (cirka 400 lag). Kodelister findes som egne lag (pdk:theme_pdk_codelist_*).\"\n  },\n  \"nb\": {\n   \"name\": \"Plandata.dk (WFS)\",\n   \"description\": \"Danmarks digitale planer: lokalplaner med delområder og byggefelt, kommuneplanrammer, tillegg og sonekart som WFS-lag i GeoJSON. Hent et lag som kart, eller en hel lokalplan som plan med plannummer eller planid.\",\n   \"notes\": \"Lagene leses fra tjenesten når kilden åpnes (cirka 400 lag). Kodelister finnes som egne lag (pdk:theme_pdk_codelist_*).\"\n  },\n  \"fi\": {\n   \"name\": \"Plandata.dk (WFS)\",\n   \"description\": \"Tanskan digitaaliset kaavat: paikalliskaavat osa-alueineen ja rakennusaloineen, kuntakaavan kehykset, täydennykset ja kaavoitusvyöhykkeet WFS-tasoina GeoJSON-muodossa. Nouda taso karttana tai koko paikalliskaava kaavana kaavanumerolla tai planid-tunnuksella.\",\n   \"notes\": \"Tasot luetaan palvelusta, kun lähde avataan (noin 400 tasoa). Koodistot ovat omia tasoja (pdk:theme_pdk_codelist_*).\"\n  },\n  \"is\": {\n   \"name\": \"Plandata.dk (WFS)\",\n   \"description\": \"Stafrænt skipulag Danmerkur: staðbundið skipulag með undirsvæðum og byggingarreitum, rammar sveitarfélagsskipulags, viðbætur og svæðisskipting sem WFS-lög í GeoJSON. Sæktu lag sem kort eða heilt staðbundið skipulag sem skipulag með skipulagsnúmeri eða planid.\",\n   \"notes\": \"Lögin eru lesin úr þjónustunni þegar uppsprettan er opnuð (um 400 lög). Kóðalistar eru eigin lög (pdk:theme_pdk_codelist_*).\"\n  }\n }\n}\n");
